    window.autoSuspendAllNonPurchasers = async function(isSilent = false) {
        if (!isSilent) {
            if (!confirm(`⚡ [미구매자 일괄 자동 정지 검사]\n\n직전 주차 실구매 미등록 일반 회원을 전수 검사하여 자동으로 이용 정지 처리하시겠습니까?\n(영구 사용 회원 및 신규 유예 회원은 제외됩니다)`)) return;
        }
        
        if (!window.db) {
            if (!isSilent) alert('DB 연결이 필요합니다.');
            return;
        }

        try {
            if (!isSilent) showToast('🔍 전 회원 실구매 이력 전수 검사 중...');
            const snapshot = await window.db.collection('lotto_users').get();
            let suspendedCount = 0;
            let activeCount = 0;
            let permanentCount = 0;
            const latestRound = getLatestDrawnRound();

            for (const doc of snapshot.docs) {
                const userId = doc.id;
                const data = doc.data();
                if (userId === 'master' || userId === 'admin' || data.isAdmin === true || data.role === 'admin') {
                    permanentCount++;
                    continue;
                }

                const pStatus = await checkUserWeeklyPurchaseStatus(userId, data);
                if (pStatus.isPermanent) {
                    permanentCount++;
                    continue;
                }

                if (!pStatus.isGracePeriod && !pStatus.hasPurchased) {
                    if (data.status === 'active') {
                        const reason = `제 ${latestRound}회차 실구매 미등록으로 인한 자동 이용정지`;
                        await window.db.collection('lotto_users').doc(userId).update({
                            status: 'suspended_nopurchase',
                            suspensionReason: reason,
                            suspendedAt: new Date().toISOString()
                        });
                        suspendedCount++;
                    }
                } else {
                    activeCount++;
                }
            }

            if (!isSilent) {
                alert(`✅ 일괄 검사 완료!\n\n- 신규 정지 처리: ${suspendedCount}명\n- 정상 구매 회원: ${activeCount}명\n- 영구 사용 회원(면제): ${permanentCount}명`);
                loadUserList();
            } else {
                console.log(`[Background Auto-Suspend on Draw] Suspended: ${suspendedCount}, Active: ${activeCount}, Exempt: ${permanentCount}`);
                if (suspendedCount > 0) {
                    showToast(`⚡ 최신 당첨 발표에 따라 미구매 회원 ${suspendedCount}명이 자동 정지되었습니다.`);
                }
            }
            return { suspendedCount, activeCount, permanentCount };
        } catch(e) {
            console.error('[Batch Auto Suspend Error]', e);
            if (!isSilent) alert('일괄 처리 중 오류가 발생했습니다.');
        }
    };


    // ========================================================
    // 🔄 [관리자] 회원 약관 동의 & 카카오 알림 권한 초기화 기능
    // ========================================================
    window.resetUserConsent = async function(userId) {
        if (!userId || !window.db) return;
        
        const confirmMsg = `🔄 [${userId}] 사용자의 필수 약관 동의 및 카카오 권한을 초기화하시겠습니까?\n\n` +
            `• 계정 자체는 삭제되지 않고 안전하게 유지됩니다.\n` +
            `• 해당 사용자가 다음에 로그인/접속할 때 필수 약관 서약 팝업과 카카오 메시지 권한 동의창이 다시 표시됩니다.`;
        
        if (!confirm(confirmMsg)) return;

        try {
            showToast(`🔄 [${userId}] 동의 내역 초기화 중...`);
            
            // 1. lotto_users 문서 내 agreementDoc, agreedTerms, kakaoAuth 초기화
            await window.db.collection('lotto_users').doc(userId).set({
                agreementDoc: null,
                agreedTerms: null,
                kakaoAuth: {
                    accessToken: '',
                    refreshToken: '',
                    hasTalkMessageScope: false,
                    updatedAt: new Date().toISOString()
                }
            }, { merge: true });

            // 2. lotto_agreements 컬렉션 내 서약서 삭제
            try {
                await window.db.collection('lotto_agreements').doc(userId).delete();
            } catch(e) {}

            // 3. 만약 현재 관리자 본인 계정인 경우 세션 플래그도 초기화
            if (userId === SafeAuth.get()) {
                try { sessionStorage.removeItem('kakao_consent_dismissed'); } catch(e){}
            }

            showToast(`🎉 [${userId}] 약관 및 카카오 권한 동의가 초기화되었습니다. 다음 접속 시 다시 팝업됩니다.`);
            if (typeof window.loadUserList === 'function') window.loadUserList();
        } catch (err) {
            console.error('[Reset User Consent Error]', err);
            alert('⚠️ 동의 초기화 중 오류가 발생했습니다: ' + (err.message || err));
        }
    };

