function appendScrapingLog(msg, type = 'info') {
    const terminal = document.getElementById('scrapingLogTerminal');
    if (!terminal) {
        console.log(`[ScrapeLog:${type}] ${msg}`);
        return;
    }

    const time = new Date().toLocaleTimeString('ko-KR', { hour12: false });
    const row = document.createElement('div');
    row.style.display = 'flex';
    row.style.gap = '8px';
    row.style.alignItems = 'flex-start';

    let color = '#94a3b8'; // info
    let icon = 'ℹ️';

    if (type === 'success') {
        color = '#34d399';
        icon = '✅';
    } else if (type === 'warn') {
        color = '#fbbf24';
        icon = '⚠️';
    } else if (type === 'error') {
        color = '#f87171';
        icon = '❌';
    } else if (type === 'header') {
        color = '#38bdf8';
        icon = '🚀';
    } else if (type === 'detail') {
        color = '#cbd5e1';
        icon = '↳';
    } else if (type === 'save') {
        color = '#a78bfa';
        icon = '💾';
    }

    row.innerHTML = `
        <span style="color: #64748b; font-size: 0.75rem; min-width: 65px; font-family: monospace;">[${time}]</span>
        <span style="color: ${color}; font-size: 0.82rem; word-break: break-all; flex: 1;">${icon} ${msg}</span>
    `;

    terminal.appendChild(row);
    terminal.scrollTop = terminal.scrollHeight;
}

